declare(strict_types=1);
namespace Sexogate;
use Brick\Math\BigInteger;
final class Returns
{
    public function __construct(private Database $db,private Config $config){}
    public function request(string $order,?string $token,string $variant,int $quantity,string $reason,string $seal,string $key,?string $user=null):array
    {
        RuleViolation::ensure((new Commerce($this->db,$this->config))->order($order,$token,$user),'ORDER_NOT_FOUND','Sipariş bulunamadı.',404);RuleViolation::ensure($quantity>0&&$quantity<=1000000&&mb_strlen(trim($reason))>=5&&mb_strlen($reason)<=2000&&in_array($seal,['unopened','opened','unknown'],true),'INVALID_RETURN','İade adedi, gerekçesi ve mühür durumunu kontrol edin.',400);
        return (new Audit($this->db))->command(new Principal($user??'guest:'.hash('sha256',$token??''),'customer',false),$key,['return-request',$order,$variant,$quantity,$reason,$seal],function()use($order,$variant,$quantity,$reason,$seal){$o=$this->db->one('SELECT payment_status FROM orders WHERE id=? FOR UPDATE',[$order]);RuleViolation::ensure($o&&in_array($o['payment_status'],['succeeded','partially_refunded'],true),'RETURN_NOT_ALLOWED','Bu sipariş için iade başvurusu alınamıyor.');$line=$this->db->one('SELECT quantity FROM order_items WHERE order_id=? AND variant_id=?',[$order,$variant]);$held=(int)$this->db->one("SELECT COALESCE(SUM(quantity),0) n FROM returns WHERE order_id=? AND variant_id=? AND status<>'rejected'",[$order,$variant])['n'];RuleViolation::ensure($line&&$held+$quantity<=(int)$line['quantity'],'RETURN_QUANTITY','İade adedi satın alınan miktarı aşıyor.');$id=Database::id();$this->db->execute('INSERT INTO returns(id,order_id,variant_id,quantity,reason,seal_status,undispatched_quantity) VALUES(?,?,?,?,?,?,?)',[$id,$order,$variant,$quantity,$reason,$seal,$this->undispatched($order,$variant,$quantity)]);return ['id'=>$id,'status'=>'requested'];});
    }
    private function undispatched(string $order,string $variant,int $quantity,?string $excluding=null):int
    {$sent=(int)$this->db->one('SELECT COALESCE(SUM(i.quantity),0) n FROM shipment_items i JOIN shipments s ON s.id=i.shipment_id WHERE s.order_id=? AND i.variant_id=?',[$order,$variant])['n'];$other=(int)$this->db->one("SELECT COALESCE(SUM(quantity-undispatched_quantity),0) n FROM returns WHERE order_id=? AND variant_id=? AND status<>'rejected' AND(? IS NULL OR id<>?)",[$order,$variant,$excluding,$excluding])['n'];return max(0,$quantity-max(0,$sent-$other));}
    private function row(string $id):array
    {$link=$this->db->one('SELECT order_id FROM returns WHERE id=?',[$id]);RuleViolation::ensure($link,'RETURN_NOT_FOUND','İade bulunamadı.',404);$this->db->one('SELECT id FROM orders WHERE id=? FOR UPDATE',[$link['order_id']]);return $this->db->one('SELECT * FROM returns WHERE id=? FOR UPDATE',[$id]);}
    public function decide(string $id,bool $approved,string $reason,string $key,Principal $actor):array
    {$actor->require('returns',true);RuleViolation::ensure(in_array($actor->role,['admin','support'],true),'FORBIDDEN','İade kararı için müşteri hizmetleri yetkisi gerekir.',403);RuleViolation::ensure(mb_strlen(trim($reason))>=5&&mb_strlen($reason)<=2000,'REASON_REQUIRED','Karar gerekçesi gerekir.',400);return (new Audit($this->db))->command($actor,$key,['return-decision',$id,$approved,$reason],function()use($id,$approved,$reason,$actor){$r=$this->row($id);RuleViolation::ensure($r['status']==='requested','RETURN_STATE','Bu iadenin karar aşaması tamamlanmış.');$status=$approved?'approved':'rejected';if($approved){$undispatched=$this->undispatched($r['order_id'],$r['variant_id'],(int)$r['quantity'],$id);$this->db->execute('UPDATE returns SET undispatched_quantity=? WHERE id=?',[$undispatched,$id]);if($undispatched>0)$this->db->execute("UPDATE fulfillment_tasks t JOIN fulfillment_task_items i ON i.task_id=t.id SET t.status='cancelled',t.updated_at=CURRENT_TIMESTAMP(3) WHERE t.order_id=? AND i.variant_id=? AND t.status IN('picking','packing','packed')",[$r['order_id'],$r['variant_id']]);}$this->db->execute('UPDATE returns SET status=?,decision_reason=?,updated_at=CURRENT_TIMESTAMP(3) WHERE id=?',[$status,$reason,$id]);(new Audit($this->db))->record($actor,$status,'returns',$id);return ['id'=>$id,'status'=>$status];});}
    public function receive(string $id,string $reference,string $key,Principal $actor):array
    {
        $actor->require('shipping',true);RuleViolation::ensure(mb_strlen(trim($reference))>=5&&mb_strlen($reference)<=500,'REFERENCE_REQUIRED','Teslim alma referansı gerekir.',400);
        return (new Audit($this->db))->command($actor,$key,['return-receive',$id,$reference],function()use($id,$reference,$actor){$inventory=new Inventory($this->db,$this->config);$inventory->definition('bundle-definition');$r=$this->row($id);RuleViolation::ensure($r['status']==='approved','RETURN_STATE','İade teslim almaya uygun değil.');$line=$this->db->one('SELECT snapshot,fulfillment_source FROM order_items WHERE order_id=? AND variant_id=?',[$r['order_id'],$r['variant_id']]);RuleViolation::ensure($line['fulfillment_source']==='warehouse','SUPPLIER_RETURN_ROUTE','Tedarikçi iadesi kendi depo stoğuna alınamaz.');$snapshot=json_decode($line['snapshot'],true);$parts=$snapshot['bundleComponents']??[];$parts=$parts?:[['variantId'=>$r['variant_id'],'quantity'=>1]];usort($parts,fn($a,$b)=>strcmp($a['variantId'],$b['variantId']));RuleViolation::ensure(count($parts)<=100&&count(array_unique(array_column($parts,'variantId')))===count($parts),'RETURN_SNAPSHOT_INVALID','Satış bileşenleri doğrulanamadı.');
            foreach($parts as $part){$v=$part['variantId'];$quantity=(int)$part['quantity']*(int)$r['quantity'];RuleViolation::ensure($quantity>0&&$quantity<=1000000&&!$this->db->one('SELECT bundle_variant_id FROM bundle_components WHERE bundle_variant_id=?',[$v]),'RETURN_PHYSICAL_TARGET','Satıştaki fiziksel bileşen artık bu girişe uygun değil.');$b=$this->db->one("SELECT on_hand FROM inventory_balance WHERE variant_id=? AND warehouse_id='main' FOR UPDATE",[$v]);RuleViolation::ensure($b,'INVENTORY_NOT_FOUND','İade stok hedefi bulunamadı.');$this->db->execute("UPDATE inventory_balance SET quarantine=quarantine+? WHERE variant_id=? AND warehouse_id='main'",[$quantity,$v]);$this->db->execute("INSERT INTO return_stock_lines(return_id,variant_id,warehouse_id,quantity) VALUES(?,?,'main',?)",[$id,$v,$quantity]);$this->db->execute("INSERT INTO inventory_movements(variant_id,warehouse_id,type,quantity,quarantine_quantity,reason,reference,actor_id) VALUES(?,'main','return_received',0,?,'İade kalite kontrolü bekliyor',?,?)",[$v,$quantity,'return-receive:'.$id.':'.$v,$actor->id]);}
            $this->db->execute("UPDATE returns SET status='received',receipt_reference=?,updated_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$reference,$id]);(new Audit($this->db))->record($actor,'receive','returns',$id);return ['id'=>$id,'status'=>'received'];});
    }
    public function inspect(string $id,string $disposition,string $reason,string $key,Principal $actor):array
    {
        $actor->require('shipping',true);RuleViolation::ensure(in_array($disposition,['restock','quarantine','dispose'],true)&&mb_strlen(trim($reason))>=5&&mb_strlen($reason)<=2000,'INVALID_QC','Kalite kararı ve gerekçesini kontrol edin.',400);
        return (new Audit($this->db))->command($actor,$key,['return-inspect',$id,$disposition,$reason],function()use($id,$disposition,$reason,$actor){(new Inventory($this->db,$this->config))->definition('bundle-definition');$r=$this->row($id);RuleViolation::ensure($r['status']==='received','RETURN_STATE','İade kalite incelemesine uygun değil.');$source=$this->db->one('SELECT fulfillment_source FROM order_items WHERE order_id=? AND variant_id=?',[$r['order_id'],$r['variant_id']]);RuleViolation::ensure($source['fulfillment_source']==='warehouse','SUPPLIER_RETURN_ROUTE','Tedarikçi iadesi için dış teslim ve kalite kanıtı kaydedilmelidir.');$lines=$this->db->all('SELECT * FROM return_stock_lines WHERE return_id=? ORDER BY variant_id',[$id]);RuleViolation::ensure($lines,'RETURN_STOCK_REQUIRED','Fiziksel teslim alma kaydı gerekir.');
            foreach($lines as $line){$v=$this->db->one('SELECT lot_tracking FROM variants WHERE id=? FOR SHARE',[$line['variant_id']]);$b=$this->db->one('SELECT quarantine FROM inventory_balance WHERE variant_id=? AND warehouse_id=? FOR UPDATE',[$line['variant_id'],$line['warehouse_id']]);RuleViolation::ensure($b&&(int)$b['quarantine']>=(int)$line['quantity'],'QUARANTINE_CONFLICT','Karantina miktarı doğrulanamadı.');if($disposition==='restock')RuleViolation::ensure($r['seal_status']==='unopened'&&!(bool)$v['lot_tracking']&&!$this->db->one('SELECT rl.reservation_id FROM reservation_lots rl JOIN reservations rs ON rs.id=rl.reservation_id WHERE rs.order_id=? AND rs.variant_id=? LIMIT 1',[$r['order_id'],$line['variant_id']])&&!$this->db->one('SELECT bundle_variant_id FROM bundle_components WHERE bundle_variant_id=?',[$line['variant_id']]),'RESTOCK_NOT_ALLOWED','Açılmış, mühürü belirsiz veya lotu doğrulanmamış ürün satışa dönemez.');
                if($disposition!=='quarantine'){$add=$disposition==='restock'?(int)$line['quantity']:0;$q=(int)$line['quantity'];$this->db->execute('UPDATE inventory_balance SET quarantine=quarantine-?,on_hand=on_hand+? WHERE variant_id=? AND warehouse_id=?',[$q,$add,$line['variant_id'],$line['warehouse_id']]);$this->db->execute('INSERT INTO inventory_movements(variant_id,warehouse_id,type,quantity,quarantine_quantity,reason,reference,actor_id) VALUES(?,?,?,?,?,?,?,?)',[$line['variant_id'],$line['warehouse_id'],'return_'.$disposition,$add,-$q,$reason,'return-qc:'.$id.':'.$line['variant_id'],$actor->id]);}}
            $this->db->execute("UPDATE returns SET status='inspected',disposition=?,quality_notes=?,updated_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$disposition,$reason,$id]);(new Audit($this->db))->record($actor,'inspect','returns',$id,['disposition'=>$disposition]);return ['id'=>$id,'status'=>'inspected'];});
    }
    public function refund(string $id,string $key,Principal $actor):array
    {
        $actor->require('finance',true);
        return (new Audit($this->db))->command($actor,$key,['return-refund',$id],function()use($id,$actor){$r=$this->row($id);$old=$this->db->one('SELECT id,amount_minor,status FROM refunds WHERE return_id=? FOR UPDATE',[$id]);if($old)return ['id'=>$old['id'],'amountMinor'=>(int)$old['amount_minor'],'status'=>$old['status']];RuleViolation::ensure($r['status']==='inspected','RETURN_STATE','Para iadesinden önce teslim alma ve kalite incelemesi gerekir.');$line=$this->db->one('SELECT * FROM order_items WHERE order_id=? AND variant_id=?',[$r['order_id'],$r['variant_id']]);$p=$this->db->one('SELECT * FROM payments WHERE order_id=? FOR UPDATE',[$r['order_id']]);RuleViolation::ensure($p&&in_array($p['status'],['succeeded','partially_refunded'],true),'PAYMENT_NOT_REFUNDABLE','Tahsilat iade işlemine uygun değil.');$previous=(int)$this->db->one('SELECT COALESCE(SUM(r.quantity),0) n FROM returns r JOIN refunds f ON f.return_id=r.id WHERE r.order_id=? AND r.variant_id=?',[$r['order_id'],$r['variant_id']])['n'];$q=(int)$r['quantity'];$n=(int)$line['quantity'];RuleViolation::ensure($previous+$q<=$n,'REFUND_QUANTITY','İade adedi satılan miktarı aşıyor.');$portion=fn(int $v)=>BigInteger::of($v)->multipliedBy($previous+$q)->quotient($n)->minus(BigInteger::of($v)->multipliedBy($previous)->quotient($n))->toInt();$discount=$portion((int)$line['discount_minor']);$tax=$portion((int)$line['tax_minor']);$amount=Money::multiply((int)$line['unit_minor'],$q)-$discount;$held=(int)$this->db->one("SELECT COALESCE(SUM(amount_minor),0) n FROM refunds WHERE payment_id=?",[$p['id']])['n'];RuleViolation::ensure($amount>0&&$held+$amount<=(int)$p['amount_minor'],'REFUND_AMOUNT','İade toplamı tahsilatı aşıyor.');$refund=Database::id();$this->db->execute('INSERT INTO refunds(id,return_id,payment_id,amount_minor,tax_minor,discount_minor) VALUES(?,?,?,?,?,?)',[$refund,$id,$p['id'],$amount,$tax,$discount]);
            if($p['provider']==='test'){RuleViolation::ensure($this->config->local()&&$this->config->get('payment_provider')==='test','TEST_PROVIDER_DISABLED','Test iadesi kapalı.',503);$total=(int)$p['refunded_minor']+$amount;$status=$total===(int)$p['amount_minor']?'refunded':'partially_refunded';$this->db->execute("UPDATE refunds SET status='succeeded',provider_reference=? WHERE id=?",['test-refund:'.$refund,$refund]);$this->db->execute('UPDATE payments SET refunded_minor=?,status=?,updated_at=CURRENT_TIMESTAMP(3) WHERE id=?',[$total,$status,$p['id']]);$this->db->execute('UPDATE orders SET payment_status=?,updated_at=CURRENT_TIMESTAMP(3) WHERE id=?',[$status,$r['order_id']]);$this->db->execute("UPDATE returns SET status='refunded',updated_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$id]);$result='succeeded';}
            else{RuleViolation::ensure($p['provider']==='stripe','REFUND_PROVIDER_UNSUPPORTED','Sağlayıcı iadesi desteklenmiyor.',503);$this->db->execute("UPDATE returns SET status='refund_pending',updated_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$id]);(new Commerce($this->db,$this->config))->enqueue('payment.refund',['refundId'=>$refund],'refund:'.$refund);$result='pending';}(new Audit($this->db))->record($actor,'refund','returns',$id,['amountMinor'=>$amount]);return ['id'=>$refund,'amountMinor'=>$amount,'status'=>$result];});
    }
}
